package com.example.demo.adapters.jdbc;

import com.example.demo.domain.RequestReceipt;
import com.example.demo.application.RequestReceipts;
import java.util.Optional;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;

/**
 * Receipts in PostgreSQL, claimed with a single atomic statement.
 *
 * <p>The claim is {@code insert ... on conflict do nothing returning}: one round
 * trip and one decision. A returned row means this caller won the key; no row
 * means somebody else already holds it. Doing the obvious thing instead — select,
 * then insert if absent — leaves a window where two callers both see nothing and
 * both proceed, which is the exact race this class exists to close.
 *
 * <p>The column is {@code idempotency_key} rather than {@code key}: the latter
 * is a keyword in enough dialects that it is not worth the argument.
 */
@Repository
public final class JdbcRequestReceipts implements RequestReceipts {

    private final JdbcClient jdbc;

    public JdbcRequestReceipts(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    @Override
    public Optional<RequestReceipt> claim(String scope, String key, String requestHash) {
        Optional<Integer> won = jdbc.sql(
                        """
                        insert into request_receipts (scope, idempotency_key, request_hash, status, created_at)
                        values (?, ?, ?, 0, now())
                        on conflict (scope, idempotency_key) do nothing
                        returning 1
                        """)
                .params(scope, key, requestHash)
                .query(Integer.class)
                .optional();
        if (won.isPresent()) {
            // Claimed it: there is nothing to replay, so the caller does the work.
            return Optional.empty();
        }
        return jdbc.sql(
                        """
                        select scope, idempotency_key, request_hash, status, response_body, created_at
                          from request_receipts
                         where scope = ? and idempotency_key = ?
                        """)
                .params(scope, key)
                .query((rs, row) -> new RequestReceipt(
                        rs.getString("scope"),
                        rs.getString("idempotency_key"),
                        rs.getString("request_hash"),
                        rs.getInt("status"),
                        Optional.ofNullable(rs.getString("response_body")),
                        rs.getTimestamp("created_at").toInstant()))
                .optional();
    }

    @Override
    public void complete(String scope, String key, int status, String responseBody) {
        jdbc.sql(
                        """
                        update request_receipts
                           set status = ?, response_body = ?
                         where scope = ? and idempotency_key = ?
                        """)
                .params(status, responseBody, scope, key)
                .update();
    }
}
